/* UE3's DECLARE_CLASS, as this build expands it: every `push "Engine"; call GetPrivateStaticClass..;
 * add esp, 4; mov [PrivateStaticClass], eax; call InitializePrivateStaticClass..` in the exe is an
 * inlined TClass::StaticClass() (data/ue3_layout.json lists each class's addresses). */
enum EInternal { EC_Internal };
inline void* operator new(SIZE_T Size, EInternal* Mem) { return (void*)Mem; }
enum EStaticConstructor { EC_StaticConstructor };
#define DECLARE_BASE_CLASS(TClass, TSuperClass, TStaticFlags, TStaticCastFlags, TPackage) \
public: \
    enum { StaticClassFlags = TStaticFlags }; \
    enum { StaticClassCastFlags = TStaticCastFlags }; \
    typedef TSuperClass Super; \
    typedef TClass ThisClass; \
    static UClass* PrivateStaticClass; \
    static UClass* GetPrivateStaticClass##TClass(const TCHAR* Package); \
    static void InitializePrivateStaticClass##TClass(); \
    static UClass* StaticClass() \
    { \
        if (!PrivateStaticClass) \
        { \
            PrivateStaticClass = GetPrivateStaticClass##TClass(TEXT(#TPackage)); \
            InitializePrivateStaticClass##TClass(); \
        } \
        return PrivateStaticClass; \
    }
/* every class but UObject: its destructor and the constructor UClass calls (a placement new; the
 * compiler's null test is the `test esi, esi` in each InternalConstructor) */
#define DECLARE_CLASS(TClass, TSuperClass, TStaticFlags, TStaticCastFlags, TPackage) \
    DECLARE_BASE_CLASS(TClass, TSuperClass, TStaticFlags, TStaticCastFlags, TPackage) \
    virtual ~TClass() { ConditionalDestroy(); } \
    friend FArchive& operator<<(FArchive& Ar, TClass*& Res) { return Ar << *(UObject**)&Res; } \
    static void InternalConstructor(void* X) { new((EInternal*)X) TClass; }
/* objects of this class live inside a TWithinClass (UClass::ClassWithin) */
#define DECLARE_WITHIN(TWithinClass) \
    typedef class TWithinClass WithinClass; TWithinClass* GetOuter##TWithinClass() const { return (TWithinClass*)Outer; }

/* UE3 compiles its classes packed to 4 on Win32 (and keeps MS_ALIGN types aligned) */
